def _norm(language: str | None) -> str:
    """Normalise a Home Assistant language tag (e.g. "en-GB") to a table key."""
    lang = (language or _FALLBACK).split("-")[0].lower()
    return lang if lang in ANOMALIES else _FALLBACK


def describe(code: int, language: str | None = _FALLBACK) -> str:
    """Return a localised description for a boiler fault code.

    Code 0 is the healthy "no faults" state (shown without an ``E`` prefix).
    Unknown codes fall back to the generic "not recognised" text; unknown
    languages fall back to English.
    """
    lang = _norm(language)
    table = ANOMALIES[lang]
    if code == 0:
        return (table.get(0) or ANOMALIES[_FALLBACK][0])[:_MAX_STATE]
    text = (
        table.get(code)
        or ANOMALIES[_FALLBACK].get(code)
        or DEFAULT_DESCRIPTION.get(lang)
        or DEFAULT_DESCRIPTION[_FALLBACK]
    )
    return f"E{code}: {text}"[:_MAX_STATE]
